75	pub fn embedded_curve_add(
76	    input1: [FieldElement; 3],
77	    input2: [FieldElement; 3],
78	) -> Result<(FieldElement, FieldElement, FieldElement), BlackBoxResolutionError> {
79	    let point1 = create_point(input1[0], input1[1], input1[2] == FieldElement::one())
80	        .map_err(|e| BlackBoxResolutionError::Failed(BlackBoxFunc::EmbeddedCurveAdd, e))?;
81	    let point2 = create_point(input2[0], input2[1], input2[2] == FieldElement::one())
82	        .map_err(|e| BlackBoxResolutionError::Failed(BlackBoxFunc::EmbeddedCurveAdd, e))?;
83	    let res = grumpkin::SWAffine::from(point1 + point2);
84	    if let Some((res_x, res_y)) = res.xy() {
85	        Ok((
86	            FieldElement::from_repr(*res_x),
87	            FieldElement::from_repr(*res_y),
88	            FieldElement::from(res.is_zero() as u128),
89	        ))
90	    } else if res.is_zero() {
91	        Ok((FieldElement::from(0_u128), FieldElement::from(0_u128), FieldElement::from(1_u128)))
92	    } else {
93	        Err(BlackBoxResolutionError::Failed(
94	            BlackBoxFunc::EmbeddedCurveAdd,
95	            "Point is not on curve".to_string(),
96	        ))
97	    }
98	}
