100	fn create_point(
101	    x: FieldElement,
102	    y: FieldElement,
103	    is_infinite: bool,
104	) -> Result<grumpkin::SWAffine, String> {
105	    if is_infinite {
106	        return Ok(grumpkin::SWAffine::zero());
107	    }
108	    let point = grumpkin::SWAffine::new_unchecked(x.into_repr(), y.into_repr());
109	    if !point.is_on_curve() {
110	        return Err(format!("Point ({}, {}) is not on curve", x.to_hex(), y.to_hex()));
111	    };
112	    if !point.is_in_correct_subgroup_assuming_on_curve() {
113	        return Err(format!("Point ({}, {}) is not in correct subgroup", x.to_hex(), y.to_hex()));
114	    };
115	    Ok(point)
116	}
