15	const NUM_DEFAULT_GENERATORS: usize = 8;
16	
17	fn default_generators() -> &'static [Affine<GrumpkinConfig>; NUM_DEFAULT_GENERATORS] {
18	    static INSTANCE: OnceLock<[Affine<GrumpkinConfig>; NUM_DEFAULT_GENERATORS]> =
19	        OnceLock::new();
20	    INSTANCE.get_or_init(|| {
21	        _derive_generators(DEFAULT_DOMAIN_SEPARATOR, NUM_DEFAULT_GENERATORS as u32, 0)
22	            .try_into()
